export default JSON.parse('{"work":{"id":"yan-tie-lun","schoolId":"histories","title":"鹽鐵論","genreStrategy":"parallel","sourceNote":"版本來源自通行本及校勘附記。","chapterIds":["yan-tie-lun_ch-1","yan-tie-lun_ch-2","yan-tie-lun_ch-3","yan-tie-lun_ch-4"],"totalChars":5076},"chapters":[{"id":"yan-tie-lun_ch-1","workId":"yan-tie-lun","order":1,"title":"本議","difficulty":4,"estimatedMinutes":10,"passageIds":["yan-tie-lun_ch-1_p-1","yan-tie-lun_ch-1_p-2","yan-tie-lun_ch-1_p-3","yan-tie-lun_ch-1_p-4","yan-tie-lun_ch-1_p-5","yan-tie-lun_ch-1_p-6","yan-tie-lun_ch-1_p-7","yan-tie-lun_ch-1_p-8","yan-tie-lun_ch-1_p-9","yan-tie-lun_ch-1_p-10","yan-tie-lun_ch-1_p-11","yan-tie-lun_ch-1_p-12"],"tags":[]},{"id":"yan-tie-lun_ch-2","workId":"yan-tie-lun","order":2,"title":"力耕","difficulty":4,"estimatedMinutes":10,"passageIds":["yan-tie-lun_ch-2_p-1","yan-tie-lun_ch-2_p-2","yan-tie-lun_ch-2_p-3","yan-tie-lun_ch-2_p-4","yan-tie-lun_ch-2_p-5","yan-tie-lun_ch-2_p-6"],"tags":[]},{"id":"yan-tie-lun_ch-3","workId":"yan-tie-lun","order":3,"title":"通有","difficulty":4,"estimatedMinutes":10,"passageIds":["yan-tie-lun_ch-3_p-1","yan-tie-lun_ch-3_p-2","yan-tie-lun_ch-3_p-3","yan-tie-lun_ch-3_p-4","yan-tie-lun_ch-3_p-5","yan-tie-lun_ch-3_p-6"],"tags":[]},{"id":"yan-tie-lun_ch-4","workId":"yan-tie-lun","order":4,"title":"錯幣","difficulty":4,"estimatedMinutes":10,"passageIds":["yan-tie-lun_ch-4_p-1","yan-tie-lun_ch-4_p-2","yan-tie-lun_ch-4_p-3","yan-tie-lun_ch-4_p-4","yan-tie-lun_ch-4_p-5","yan-tie-lun_ch-4_p-6"],"tags":[]}],"passages":[{"id":"yan-tie-lun_ch-1_p-1","chapterId":"yan-tie-lun_ch-1","order":1,"canonicalText":"惟始元六年，有詔書使丞相、御史與所舉賢良、文學語。問民間所疾苦。","sentenceIds":["yan-tie-lun_ch-1_p-1_s-1","yan-tie-lun_ch-1_p-1_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"}]},{"id":"yan-tie-lun_ch-1_p-2","chapterId":"yan-tie-lun_ch-1","order":2,"canonicalText":"文學對曰：「竊聞治人之道，防淫佚之原，廣道德之端，抑末利而開仁義，毋示以利，然後教化可興，而風俗可移也。今郡國有鹽、鐵、酒榷，均輸，與民爭利。散敦厚之樸，成貪鄙之化。是以百姓就本者寡，趨末者眾。夫文繁則質衰，末盛則質虧。末修則民淫，本修則民愨。民愨則財用足，民侈則饑寒生。願罷鹽、鐵、酒榷、均輸，所以進本退末，廣利農業，便也。」","sentenceIds":["yan-tie-lun_ch-1_p-2_s-1","yan-tie-lun_ch-1_p-2_s-2","yan-tie-lun_ch-1_p-2_s-3","yan-tie-lun_ch-1_p-2_s-4","yan-tie-lun_ch-1_p-2_s-5","yan-tie-lun_ch-1_p-2_s-6","yan-tie-lun_ch-1_p-2_s-7","yan-tie-lun_ch-1_p-2_s-8","yan-tie-lun_ch-1_p-2_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"}]},{"id":"yan-tie-lun_ch-1_p-3","chapterId":"yan-tie-lun_ch-1","order":3,"canonicalText":"大夫曰：「匈奴背叛不臣，數為寇暴於邊鄙，備之則勞中國之士，不備則侵盜不止。先帝哀邊人之久患，苦為虜所係獲也，故修障塞。飭烽燧，屯戍以備之。邊用度不足，故興鹽、鐵，設酒榷，置均輸，蕃貨長財，以佐助邊費。今議者欲罷之，內空府庫之藏，外乏執備之用，使備塞乘城之士饑寒於邊，將何以贍之？罷之，不便也。」","sentenceIds":["yan-tie-lun_ch-1_p-3_s-1","yan-tie-lun_ch-1_p-3_s-2","yan-tie-lun_ch-1_p-3_s-3","yan-tie-lun_ch-1_p-3_s-4","yan-tie-lun_ch-1_p-3_s-5","yan-tie-lun_ch-1_p-3_s-6","yan-tie-lun_ch-1_p-3_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"}]},{"id":"yan-tie-lun_ch-1_p-4","chapterId":"yan-tie-lun_ch-1","order":4,"canonicalText":"文學曰：「孔子曰：『有國有家者，不患貧而患不均，不患寡而患不安。』故天子不言多少，諸侯不言利害，大夫不言得喪。畜仁義以風之，廣德行以懷之。是以近者親附而遠者悅服。故善克者不戰，善戰者不師，善師者不陣。修之於廟堂，而折衝還師。王者行仁政，無敵於天下，惡用費哉？」","sentenceIds":["yan-tie-lun_ch-1_p-4_s-1","yan-tie-lun_ch-1_p-4_s-2","yan-tie-lun_ch-1_p-4_s-3","yan-tie-lun_ch-1_p-4_s-4","yan-tie-lun_ch-1_p-4_s-5","yan-tie-lun_ch-1_p-4_s-6","yan-tie-lun_ch-1_p-4_s-7","yan-tie-lun_ch-1_p-4_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"}]},{"id":"yan-tie-lun_ch-1_p-5","chapterId":"yan-tie-lun_ch-1","order":5,"canonicalText":"大夫曰：「匈奴桀黠，擅恣入塞，犯厲中國，殺伐郡、縣、朔方都尉，甚悖逆不軌，宜誅討之日久矣。陛下垂大惠，哀元元之未贍，不忍暴士大夫於原野；縱難被堅執銳，有北面復匈奴之志，又欲罷鹽、鐵、均輸，擾邊用，損武略，無憂邊之心，於其義未便也。」","sentenceIds":["yan-tie-lun_ch-1_p-5_s-1","yan-tie-lun_ch-1_p-5_s-2","yan-tie-lun_ch-1_p-5_s-3","yan-tie-lun_ch-1_p-5_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"}]},{"id":"yan-tie-lun_ch-1_p-6","chapterId":"yan-tie-lun_ch-1","order":6,"canonicalText":"文學曰：「古者，貴以德而賤用兵。孔子曰：『遠人不服，則修文德以來之。既來之，則安之。』今廢道德而任兵革，興師而伐之，屯戍而備之，暴兵露師，以支久長，轉輸糧食無已，使邊境之士饑寒於外，百姓勞苦於內。立鹽、鐵，始張利官以給之，非長策也。故以罷之為便也。」","sentenceIds":["yan-tie-lun_ch-1_p-6_s-1","yan-tie-lun_ch-1_p-6_s-2","yan-tie-lun_ch-1_p-6_s-3","yan-tie-lun_ch-1_p-6_s-4","yan-tie-lun_ch-1_p-6_s-5","yan-tie-lun_ch-1_p-6_s-6","yan-tie-lun_ch-1_p-6_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"}]},{"id":"yan-tie-lun_ch-1_p-7","chapterId":"yan-tie-lun_ch-1","order":7,"canonicalText":"大夫曰：「古之立國家者，開本末之途，通有無之用，市朝以一其求，致士民，聚萬貨，農商工師各得所欲，交易而退。易曰：『通其變，使民不倦。』故工不出，則農用乏；商不出，則寶貨絕。農用乏，則穀不殖；寶貨絕，則財用匱。故鹽、鐵、均輸，所以通委財而調緩急。罷之，不便也。」","sentenceIds":["yan-tie-lun_ch-1_p-7_s-1","yan-tie-lun_ch-1_p-7_s-2","yan-tie-lun_ch-1_p-7_s-3","yan-tie-lun_ch-1_p-7_s-4","yan-tie-lun_ch-1_p-7_s-5","yan-tie-lun_ch-1_p-7_s-6","yan-tie-lun_ch-1_p-7_s-7","yan-tie-lun_ch-1_p-7_s-8","yan-tie-lun_ch-1_p-7_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"}]},{"id":"yan-tie-lun_ch-1_p-8","chapterId":"yan-tie-lun_ch-1","order":8,"canonicalText":"文學曰：「夫導民以德則民歸厚；示民以利，則民俗薄。俗薄則背義而趨利，趨利則百姓交於道而接於市。老子曰：『貧國若有餘。』非多財也，嗜慾眾而民躁也。是以王者崇本退末，以禮義防民欲，實菽粟貨財。市，商不通無用之物，工不作無用之器。故商所以通鬱滯，工所以備器械，非治國之本務也。」","sentenceIds":["yan-tie-lun_ch-1_p-8_s-1","yan-tie-lun_ch-1_p-8_s-2","yan-tie-lun_ch-1_p-8_s-3","yan-tie-lun_ch-1_p-8_s-4","yan-tie-lun_ch-1_p-8_s-5","yan-tie-lun_ch-1_p-8_s-6","yan-tie-lun_ch-1_p-8_s-7","yan-tie-lun_ch-1_p-8_s-8","yan-tie-lun_ch-1_p-8_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"}]},{"id":"yan-tie-lun_ch-1_p-9","chapterId":"yan-tie-lun_ch-1","order":9,"canonicalText":"大夫曰：「管子云：『國有沃野之饒而民不足於食者，器械不備也。有山海之貨而民不足於財者，商工不備也。』隴、蜀之丹漆旄羽，荊、揚之皮革骨象，江南之楠梓竹箭，燕、齊之魚鹽旃裘，兗、豫之漆絲絺紵，養生送終之具也，待商而通，待工而成。故聖人作為舟楫之用，以通川谷，服牛駕馬，以達陵陸；致遠窮深，所以交庶物而便百姓。是以先帝建鐵官以贍農用，開均輸以足民財；鹽、鐵、均輸，萬民所戴仰而取給者，罷之，不便也。」","sentenceIds":["yan-tie-lun_ch-1_p-9_s-1","yan-tie-lun_ch-1_p-9_s-2","yan-tie-lun_ch-1_p-9_s-3","yan-tie-lun_ch-1_p-9_s-4","yan-tie-lun_ch-1_p-9_s-5","yan-tie-lun_ch-1_p-9_s-6","yan-tie-lun_ch-1_p-9_s-7","yan-tie-lun_ch-1_p-9_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"}]},{"id":"yan-tie-lun_ch-1_p-10","chapterId":"yan-tie-lun_ch-1","order":10,"canonicalText":"文學曰：「國有沃野之饒而民不足於食者，工商盛而本業荒也；有山海之貨而民不足於財者，不務民用而淫巧眾也。故川源不能實漏卮，山海不能贍溪壑。是以盤庚萃居，舜藏黃金，高帝禁商賈不得仕宦，所以遏貪鄙之俗，而醇至誠之風也。排困市井，防塞利門，而民猶為非也，況上之為利乎？傳曰：『諸侯好利則大夫鄙，大夫鄙則士貪，士貪則庶人盜。』是開利孔為民罪梯也。」","sentenceIds":["yan-tie-lun_ch-1_p-10_s-1","yan-tie-lun_ch-1_p-10_s-2","yan-tie-lun_ch-1_p-10_s-3","yan-tie-lun_ch-1_p-10_s-4","yan-tie-lun_ch-1_p-10_s-5","yan-tie-lun_ch-1_p-10_s-6","yan-tie-lun_ch-1_p-10_s-7","yan-tie-lun_ch-1_p-10_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"}]},{"id":"yan-tie-lun_ch-1_p-11","chapterId":"yan-tie-lun_ch-1","order":11,"canonicalText":"大夫曰：「往者，郡國諸侯各以其方物貢輸，往來煩雜，物多苦惡，或不償其費。故郡國置輸官以相給運，而便遠方之貢，故曰均輸。開委府於京師，以籠貨物。賤即買，貴則賣。是以縣官不失實，商賈無所貿利，故曰平準。平準則民不失職，均輸則民齊勞逸。故平準、均輸，所以平萬物而便百姓，非開利孔而為民罪梯者也。」","sentenceIds":["yan-tie-lun_ch-1_p-11_s-1","yan-tie-lun_ch-1_p-11_s-2","yan-tie-lun_ch-1_p-11_s-3","yan-tie-lun_ch-1_p-11_s-4","yan-tie-lun_ch-1_p-11_s-5","yan-tie-lun_ch-1_p-11_s-6","yan-tie-lun_ch-1_p-11_s-7","yan-tie-lun_ch-1_p-11_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"}]},{"id":"yan-tie-lun_ch-1_p-12","chapterId":"yan-tie-lun_ch-1","order":12,"canonicalText":"文學曰：「古者之賦稅於民也，因其所工，不求所拙。農人納其穫，女工效其功。今釋其所有，責其所無。百姓賤賣貨物，以便上求。間者，郡國或令民作布絮，吏恣留難，與之為市。吏之所入，非獨齊、阿之縑，蜀、漢之布也，亦民間之所為耳。行姦賣平，農民重苦，女工再稅，未見輸之均也。縣官猥發，闔門擅市，則萬物并收。萬物并收，則物騰躍。騰躍，則商賈侔利。自市，則吏容姦。豪吏富商積貨儲物以待其急，輕賈姦吏收賤以取貴，未見準之平也。蓋古之均輸，所以齊勞逸而便貢輸，非以為利而賈萬物也。」","sentenceIds":["yan-tie-lun_ch-1_p-12_s-1","yan-tie-lun_ch-1_p-12_s-2","yan-tie-lun_ch-1_p-12_s-3","yan-tie-lun_ch-1_p-12_s-4","yan-tie-lun_ch-1_p-12_s-5","yan-tie-lun_ch-1_p-12_s-6","yan-tie-lun_ch-1_p-12_s-7","yan-tie-lun_ch-1_p-12_s-8","yan-tie-lun_ch-1_p-12_s-9","yan-tie-lun_ch-1_p-12_s-10","yan-tie-lun_ch-1_p-12_s-11","yan-tie-lun_ch-1_p-12_s-12","yan-tie-lun_ch-1_p-12_s-13","yan-tie-lun_ch-1_p-12_s-14"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"}]},{"id":"yan-tie-lun_ch-2_p-1","chapterId":"yan-tie-lun_ch-2","order":1,"canonicalText":"大夫曰：「王者塞天財，禁關市，執準守時，以輕重御民。豐年歲登，則儲積以備乏絕；凶年惡歲，則行幣物；流有餘而調不足也。昔禹水湯旱，百姓匱乏，或相假以接衣食。禹以歷山之金，湯以莊山之銅，鑄幣以贖其民，而天下稱仁。往者財用不足，戰士或不得祿，而山東被災，齊、趙大饑，賴均輸之畜，倉廩之積，戰士以奉，饑民以賑。故均輸之物，府庫之財，非所以賈萬民而專奉兵師之用，亦所以賑困乏而備水旱之災也。」","sentenceIds":["yan-tie-lun_ch-2_p-1_s-1","yan-tie-lun_ch-2_p-1_s-2","yan-tie-lun_ch-2_p-1_s-3","yan-tie-lun_ch-2_p-1_s-4","yan-tie-lun_ch-2_p-1_s-5","yan-tie-lun_ch-2_p-1_s-6","yan-tie-lun_ch-2_p-1_s-7","yan-tie-lun_ch-2_p-1_s-8","yan-tie-lun_ch-2_p-1_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"}]},{"id":"yan-tie-lun_ch-2_p-2","chapterId":"yan-tie-lun_ch-2","order":2,"canonicalText":"文學曰：「古者，十一而稅，澤梁以時入而無禁，黎民咸被南畝而不失其務。故三年耕而餘一年之蓄，九年耕有三年之蓄。此禹、湯所以備水旱而安百姓也。草萊不闢，田疇不治，雖擅山海之財，通百末之利，猶不能贍也。是以古者尚力務本而種樹繁，躬耕趣時而衣食足，雖累凶年而人不病也。故衣食者民之本，稼穡者民之務也。二者修，則國富而民安也。《》云：『』也。」","sentenceIds":["yan-tie-lun_ch-2_p-2_s-1","yan-tie-lun_ch-2_p-2_s-2","yan-tie-lun_ch-2_p-2_s-3","yan-tie-lun_ch-2_p-2_s-4","yan-tie-lun_ch-2_p-2_s-5","yan-tie-lun_ch-2_p-2_s-6","yan-tie-lun_ch-2_p-2_s-7","yan-tie-lun_ch-2_p-2_s-8","yan-tie-lun_ch-2_p-2_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"}]},{"id":"yan-tie-lun_ch-2_p-3","chapterId":"yan-tie-lun_ch-2","order":3,"canonicalText":"大夫曰：「賢聖治家非一寶，富國非一道。昔管仲以權譎霸，而紀氏以強本亡。使治家養生必於農，則舜不甄陶而伊尹不為庖。故善為國者，天下之下我高，天下之輕我重。以末易其本，以虛蕩其實。今山澤之財，均輸之藏，所以御輕重而役諸侯也。汝、漢之金，纖微之貢，所以誘外國而釣胡、羌之寶也。夫中國一端之縵，得匈奴累金之物，而損敵國之用。是以騾驢馲駝，銜尾入塞，驒騱騵馬，盡為我畜，鼲貂狐貉，采旃文罽，充於內府，而璧玉珊瑚琉璃，咸為國之寶。是則外國之物內流，而利不外泄也。異物內流則國用饒，利不外泄則民用給矣。《》曰：『』」","sentenceIds":["yan-tie-lun_ch-2_p-3_s-1","yan-tie-lun_ch-2_p-3_s-2","yan-tie-lun_ch-2_p-3_s-3","yan-tie-lun_ch-2_p-3_s-4","yan-tie-lun_ch-2_p-3_s-5","yan-tie-lun_ch-2_p-3_s-6","yan-tie-lun_ch-2_p-3_s-7","yan-tie-lun_ch-2_p-3_s-8","yan-tie-lun_ch-2_p-3_s-9","yan-tie-lun_ch-2_p-3_s-10","yan-tie-lun_ch-2_p-3_s-11","yan-tie-lun_ch-2_p-3_s-12"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"}]},{"id":"yan-tie-lun_ch-2_p-4","chapterId":"yan-tie-lun_ch-2","order":4,"canonicalText":"文學曰：「古者，商通物而不豫，工致牢而不偽。故君子耕稼田魚，其實一也。商則長詐，工則飾罵，內懷闚窬而心不怍，是以薄夫欺而敦夫薄。昔桀女樂充宮室，文繡衣裳，故伊尹高逝遊薄，而女樂終廢其國。今騾驢之用，不中牛馬之功，鼲貂旃罽，不益錦綈之實。美玉珊瑚出於昆山，珠璣犀象出於桂林，此距漢萬有餘里。計耕桑之功，資財之費，是一物而售百倍其價也，一揖而中萬鍾之粟也。夫上好珍怪，則淫服下流，貴遠方之物，則貨財外充。是以王者不珍無用以節其民，不愛奇貨以富其國。故理民之道，在於節用尚本，分土井田而已。」","sentenceIds":["yan-tie-lun_ch-2_p-4_s-1","yan-tie-lun_ch-2_p-4_s-2","yan-tie-lun_ch-2_p-4_s-3","yan-tie-lun_ch-2_p-4_s-4","yan-tie-lun_ch-2_p-4_s-5","yan-tie-lun_ch-2_p-4_s-6","yan-tie-lun_ch-2_p-4_s-7","yan-tie-lun_ch-2_p-4_s-8","yan-tie-lun_ch-2_p-4_s-9","yan-tie-lun_ch-2_p-4_s-10","yan-tie-lun_ch-2_p-4_s-11"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"}]},{"id":"yan-tie-lun_ch-2_p-5","chapterId":"yan-tie-lun_ch-2","order":5,"canonicalText":"大夫曰：「自京師東西南北，歷山川，經郡國，諸殷富大都，無非街衢五通，商賈之所湊，萬物之所殖者。故聖人因天時，智者因地財，上士取諸人，中士勞其形。長沮、桀溺，無百金之積，蹠蹻之徒，無猗頓之富，宛、周、齊、魯，商遍天下。故乃商賈之富，或累萬金，追利乘羡之所致也。富國何必用本農，足民何必井田也？」","sentenceIds":["yan-tie-lun_ch-2_p-5_s-1","yan-tie-lun_ch-2_p-5_s-2","yan-tie-lun_ch-2_p-5_s-3","yan-tie-lun_ch-2_p-5_s-4","yan-tie-lun_ch-2_p-5_s-5","yan-tie-lun_ch-2_p-5_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"}]},{"id":"yan-tie-lun_ch-2_p-6","chapterId":"yan-tie-lun_ch-2","order":6,"canonicalText":"文學曰：「洪水滔天，而有禹之績，河水泛濫，而有宣房之功。商紂暴虐，而有孟津之謀，天下煩擾，而有乘羡之富。夫上古至治，民樸而貴本、安愉而寡求。當此之時，道路罕行，市朝生草。故耕不強者無以充虛，織不強者無以掩形。雖有湊會之要，陶、宛之術，無所施其巧。自古及今，不施而得報，不勞而有功者，未之有也。」","sentenceIds":["yan-tie-lun_ch-2_p-6_s-1","yan-tie-lun_ch-2_p-6_s-2","yan-tie-lun_ch-2_p-6_s-3","yan-tie-lun_ch-2_p-6_s-4","yan-tie-lun_ch-2_p-6_s-5","yan-tie-lun_ch-2_p-6_s-6","yan-tie-lun_ch-2_p-6_s-7","yan-tie-lun_ch-2_p-6_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"}]},{"id":"yan-tie-lun_ch-3_p-1","chapterId":"yan-tie-lun_ch-3","order":1,"canonicalText":"大夫曰：「燕之涿、薊，趙之邯鄲，魏之溫軹，韓之滎陽，齊之臨淄，楚之宛、陳，鄭之陽翟，三川之二周，富冠海內，皆為天下名都，非有助之耕其野而田其地者也，居五諸之衝，跨街衢之路也。故物豐者民衍，宅近市者家富。富在術數，不在勞身；利在勢居，不在力耕也。","sentenceIds":["yan-tie-lun_ch-3_p-1_s-1","yan-tie-lun_ch-3_p-1_s-2","yan-tie-lun_ch-3_p-1_s-3","yan-tie-lun_ch-3_p-1_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"}]},{"id":"yan-tie-lun_ch-3_p-2","chapterId":"yan-tie-lun_ch-3","order":2,"canonicalText":"文學曰：「荊、揚南有桂林之饒，內有江、湖之利，左陵陽之金，右蜀、漢之材，伐木而樹穀，燔萊而播粟，火耕而水耨，地廣而饒財；然民鮆窳偷生，好衣甘食，雖白屋草廬，歌謳鼓琴，日給月單，朝歌暮戚。趙、中山帶大河，纂四通神衢，當天下之蹊，商賈錯於路，諸侯交於道；然民淫好末，侈靡而不務本，田疇不脩，男女矜飾，家無斗筲，鳴琴在室。是以楚、趙之民，均貧而寡富。宋、衛、韓、梁，好本稼穡，編戶齊民，無不家衍人給。故利在自惜，不在勢居街衢；富在儉力趣時，不在歲司羽鳩也。」","sentenceIds":["yan-tie-lun_ch-3_p-2_s-1","yan-tie-lun_ch-3_p-2_s-2","yan-tie-lun_ch-3_p-2_s-3","yan-tie-lun_ch-3_p-2_s-4","yan-tie-lun_ch-3_p-2_s-5","yan-tie-lun_ch-3_p-2_s-6","yan-tie-lun_ch-3_p-2_s-7","yan-tie-lun_ch-3_p-2_s-8","yan-tie-lun_ch-3_p-2_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"}]},{"id":"yan-tie-lun_ch-3_p-3","chapterId":"yan-tie-lun_ch-3","order":3,"canonicalText":"大夫曰：「五行：東方木，而丹、章有金銅之山；南方火，而交趾有大海之川；西方金，而蜀、隴有名材之林；北方水，而幽都有積沙之地。此天地所以均有無而通萬物也。今吳、越之竹，隋、唐之材，不可勝用，而曹、衛、梁、宋，采棺轉尸；江、湖之魚，萊、黃之鮐，不可勝食，而鄒、魯、周、韓，藜藿蔬食。天地之利無不贍，而山海之貨無不富也；然百姓匱乏，財用不足，多寡不調，而天下財不散也。」","sentenceIds":["yan-tie-lun_ch-3_p-3_s-1","yan-tie-lun_ch-3_p-3_s-2","yan-tie-lun_ch-3_p-3_s-3","yan-tie-lun_ch-3_p-3_s-4","yan-tie-lun_ch-3_p-3_s-5","yan-tie-lun_ch-3_p-3_s-6","yan-tie-lun_ch-3_p-3_s-7","yan-tie-lun_ch-3_p-3_s-8","yan-tie-lun_ch-3_p-3_s-9","yan-tie-lun_ch-3_p-3_s-10"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"}]},{"id":"yan-tie-lun_ch-3_p-4","chapterId":"yan-tie-lun_ch-3","order":4,"canonicalText":"文學曰：「古者，采椽不斲，茅茨不翦，衣布褐，飯土硎，鑄金為鉏，埏埴為器，工不造奇巧，世不寶不可衣食之物，各安其居，樂其俗，甘其食，便其器。是以遠方之物不交，而崑山之玉不至。今世俗壞而競於淫靡，女極纖微，工極技巧，雕素樸而尚珍怪，鑽山石而求金銀，沒深淵求珠璣，設機陷求犀象，張網羅求翡翠，求蠻、貉之物以眩中國，徙邛、筰之貨，致之東海，交萬里之財，曠日費功，無益於用。是以褐夫匹婦，勞疲力屈，而衣食不足也。故王者禁溢利，節漏費。溢利禁則反本，漏費節則民用給。是以生無乏資，死無轉尸也。」","sentenceIds":["yan-tie-lun_ch-3_p-4_s-1","yan-tie-lun_ch-3_p-4_s-2","yan-tie-lun_ch-3_p-4_s-3","yan-tie-lun_ch-3_p-4_s-4","yan-tie-lun_ch-3_p-4_s-5","yan-tie-lun_ch-3_p-4_s-6","yan-tie-lun_ch-3_p-4_s-7","yan-tie-lun_ch-3_p-4_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"}]},{"id":"yan-tie-lun_ch-3_p-5","chapterId":"yan-tie-lun_ch-3","order":5,"canonicalText":"大夫曰：「古者，宮室有度，輿服以庸；采椽茅茨，非先王之制也。君子節奢刺儉，儉則固。昔孫叔敖相楚，妻不衣帛，馬不秣粟。孔子曰：『不可，大儉極下。』此蟋蟀所為作也。管子曰：『不飾宮室，則材木不可勝用，不充庖廚，則禽獸不損其壽。無末利，則本業無所出，無黼黻，則女工不施。』故工商梓匠，邦國之用，器械之備也。自古有之，非獨於此。弦高販牛於周，五羖賃車入秦，公輸子以規矩，歐冶以鎔鑄。語曰：『百工居肆，以致其事。』農商交易，以利本末。山居澤處，蓬蒿堯埆，財物流通，有以均之。是以多者不獨衍，少者不獨饉。若各居其處，食其食，則是橘柚不鬻，朐鹵之鹽不出，旃罽不市，而吳、唐之材不用也。」","sentenceIds":["yan-tie-lun_ch-3_p-5_s-1","yan-tie-lun_ch-3_p-5_s-2","yan-tie-lun_ch-3_p-5_s-3","yan-tie-lun_ch-3_p-5_s-4","yan-tie-lun_ch-3_p-5_s-5","yan-tie-lun_ch-3_p-5_s-6","yan-tie-lun_ch-3_p-5_s-7","yan-tie-lun_ch-3_p-5_s-8","yan-tie-lun_ch-3_p-5_s-9","yan-tie-lun_ch-3_p-5_s-10","yan-tie-lun_ch-3_p-5_s-11","yan-tie-lun_ch-3_p-5_s-12","yan-tie-lun_ch-3_p-5_s-13","yan-tie-lun_ch-3_p-5_s-14","yan-tie-lun_ch-3_p-5_s-15","yan-tie-lun_ch-3_p-5_s-16","yan-tie-lun_ch-3_p-5_s-17"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"}]},{"id":"yan-tie-lun_ch-3_p-6","chapterId":"yan-tie-lun_ch-3","order":6,"canonicalText":"文學曰：「孟子云：『不違農時，穀不可勝食。蠶麻以時，布帛不可勝衣也。斧斤以時，材木不可勝用。田漁以時，魚肉不可勝食。』若則飾宮室，增臺榭，梓匠斲巨為小，以圓為方，上成雲氣，下成山林，則材木不足用也。男子去本為末，雕文刻鏤，以象禽獸，窮物究變，則穀不足食也。婦女飾微治細，以成文章，極伎盡巧，則絲布不足衣也。庖宰烹殺胎卵，煎炙齊和，窮極五味，則魚肉不足食也。當今世，非患禽獸不損，材木不勝，患僭侈之無窮也；非患無旃罽橘柚，患無狹廬糠糟也。」","sentenceIds":["yan-tie-lun_ch-3_p-6_s-1","yan-tie-lun_ch-3_p-6_s-2","yan-tie-lun_ch-3_p-6_s-3","yan-tie-lun_ch-3_p-6_s-4","yan-tie-lun_ch-3_p-6_s-5","yan-tie-lun_ch-3_p-6_s-6","yan-tie-lun_ch-3_p-6_s-7","yan-tie-lun_ch-3_p-6_s-8","yan-tie-lun_ch-3_p-6_s-9","yan-tie-lun_ch-3_p-6_s-10","yan-tie-lun_ch-3_p-6_s-11"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"}]},{"id":"yan-tie-lun_ch-4_p-1","chapterId":"yan-tie-lun_ch-4","order":1,"canonicalText":"大夫曰：「交幣通施，民事不及，物有所并也。計本量委，民有饑者，穀有所藏也。智者有百人之功，愚者有不更本之事。人君不調，民有相萬之富也。此其所以或儲百年之餘，或不厭糟糠也。民大富，則不可以祿使也；大彊，則不可以罰威也。非散聚均利者不齊。故人主積其食，守其用，制其有餘，調其不足，禁溢羡，厄利塗，然後百姓可家給人足也。」","sentenceIds":["yan-tie-lun_ch-4_p-1_s-1","yan-tie-lun_ch-4_p-1_s-2","yan-tie-lun_ch-4_p-1_s-3","yan-tie-lun_ch-4_p-1_s-4","yan-tie-lun_ch-4_p-1_s-5","yan-tie-lun_ch-4_p-1_s-6","yan-tie-lun_ch-4_p-1_s-7","yan-tie-lun_ch-4_p-1_s-8","yan-tie-lun_ch-4_p-1_s-9","yan-tie-lun_ch-4_p-1_s-10"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"}]},{"id":"yan-tie-lun_ch-4_p-2","chapterId":"yan-tie-lun_ch-4","order":2,"canonicalText":"文學曰：「古者，貴德而賤利，重義而輕財。三王之時，迭盛迭衰。衰則扶之，傾則定之。是以夏忠、殷敬、周文，庠序之教，恭讓之禮，粲然可得而觀也。及其後，禮義弛崩，風俗滅息，故自食祿之君子，違於義而競於財，大小相吞，淚轉相傾。此所以或儲百年之餘，或無以充虛蔽形也。古之仕者不穡，田者不漁，抱關擊柝，皆有常秩，不得兼利盡物。如此，則愚智同功，不相傾也。《》云：『』言不盡物也。」","sentenceIds":["yan-tie-lun_ch-4_p-2_s-1","yan-tie-lun_ch-4_p-2_s-2","yan-tie-lun_ch-4_p-2_s-3","yan-tie-lun_ch-4_p-2_s-4","yan-tie-lun_ch-4_p-2_s-5","yan-tie-lun_ch-4_p-2_s-6","yan-tie-lun_ch-4_p-2_s-7","yan-tie-lun_ch-4_p-2_s-8","yan-tie-lun_ch-4_p-2_s-9","yan-tie-lun_ch-4_p-2_s-10"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"}]},{"id":"yan-tie-lun_ch-4_p-3","chapterId":"yan-tie-lun_ch-4","order":3,"canonicalText":"大夫曰：「湯、文繼衰，漢興乘弊。一質一文，非苟易常也。俗弊更法，非務變古也，亦所以救失扶衰也。故教與俗改，弊與世易。夏后以玄貝，周人以紫石，後世或金錢刀布。物極而衰，終始之運也。故山澤無征，則君臣同利，刀幣無禁，則姦貞並行。夫臣富則相侈，下專利則相傾也。」","sentenceIds":["yan-tie-lun_ch-4_p-3_s-1","yan-tie-lun_ch-4_p-3_s-2","yan-tie-lun_ch-4_p-3_s-3","yan-tie-lun_ch-4_p-3_s-4","yan-tie-lun_ch-4_p-3_s-5","yan-tie-lun_ch-4_p-3_s-6","yan-tie-lun_ch-4_p-3_s-7","yan-tie-lun_ch-4_p-3_s-8","yan-tie-lun_ch-4_p-3_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"}]},{"id":"yan-tie-lun_ch-4_p-4","chapterId":"yan-tie-lun_ch-4","order":4,"canonicalText":"文學曰：「古者，市朝而無刁幣，各以其所有易所無，抱布貿絲而已。後世即有龜貝金錢，交施之也。幣數變而民滋偽。夫救偽以質，防失以禮。湯、文繼衰，革法易化，而殷、周道興。漢初乘弊，而不改易，畜利變幣，欲以反本，是猶以煎止燔，以火止沸也。上好禮則民闇飾，上好貨則下死利也。」","sentenceIds":["yan-tie-lun_ch-4_p-4_s-1","yan-tie-lun_ch-4_p-4_s-2","yan-tie-lun_ch-4_p-4_s-3","yan-tie-lun_ch-4_p-4_s-4","yan-tie-lun_ch-4_p-4_s-5","yan-tie-lun_ch-4_p-4_s-6","yan-tie-lun_ch-4_p-4_s-7","yan-tie-lun_ch-4_p-4_s-8"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"}]},{"id":"yan-tie-lun_ch-4_p-5","chapterId":"yan-tie-lun_ch-4","order":5,"canonicalText":"大夫曰：「文帝之時，縱民得鑄錢、冶鐵、煮鹽。吳王擅鄣海澤，鄧通專西山。山東奸猾，咸聚吳國，秦、雍、漢、蜀因鄧氏。吳、鄧錢布天下，故有鑄錢之禁。禁禦之法立，而奸偽息，奸偽息，則民不期於妄得，而各務其職；不反本何為？故統一，則民不二也；幣由上，則下不疑也。」","sentenceIds":["yan-tie-lun_ch-4_p-5_s-1","yan-tie-lun_ch-4_p-5_s-2","yan-tie-lun_ch-4_p-5_s-3","yan-tie-lun_ch-4_p-5_s-4","yan-tie-lun_ch-4_p-5_s-5","yan-tie-lun_ch-4_p-5_s-6","yan-tie-lun_ch-4_p-5_s-7","yan-tie-lun_ch-4_p-5_s-8","yan-tie-lun_ch-4_p-5_s-9"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"}]},{"id":"yan-tie-lun_ch-4_p-6","chapterId":"yan-tie-lun_ch-4","order":6,"canonicalText":"文學曰：「往古，幣眾財通而民樂。其後，稍去舊幣，更行白金龜龍，民多巧新幣。幣數易而民益疑。於是廢天下諸錢，而專命水衡三官作。吏匠侵利，或不中式，故有薄厚輕重。農人不習，物類比之，信故疑新，不知姦貞。商賈以美貿惡，以半易倍。買則失實，賣則失理，其疑或滋益甚。夫鑄偽金錢以有法，而錢之善惡無增損於故。擇錢則物稽滯，而用人尤被其苦。春秋曰：『算不及蠻、夷則不行。』故王者外不鄣海澤以便民用，內不禁刀幣以通民施。」","sentenceIds":["yan-tie-lun_ch-4_p-6_s-1","yan-tie-lun_ch-4_p-6_s-2","yan-tie-lun_ch-4_p-6_s-3","yan-tie-lun_ch-4_p-6_s-4","yan-tie-lun_ch-4_p-6_s-5","yan-tie-lun_ch-4_p-6_s-6","yan-tie-lun_ch-4_p-6_s-7","yan-tie-lun_ch-4_p-6_s-8","yan-tie-lun_ch-4_p-6_s-9","yan-tie-lun_ch-4_p-6_s-10","yan-tie-lun_ch-4_p-6_s-11","yan-tie-lun_ch-4_p-6_s-12","yan-tie-lun_ch-4_p-6_s-13"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/yan-tie-lun/zh"}]}],"sentences":[{"id":"yan-tie-lun_ch-1_p-1_s-1","passageId":"yan-tie-lun_ch-1_p-1","order":1,"canonicalText":"惟始元六年，有詔書使丞相、御史與所舉賢良、文學語。","chunks":[["惟始元六年，有詔書使丞相、御史與所舉賢良、文學語。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-1_s-2","passageId":"yan-tie-lun_ch-1_p-1","order":2,"canonicalText":"問民間所疾苦。","chunks":[["問民間所疾苦。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-2_s-1","passageId":"yan-tie-lun_ch-1_p-2","order":1,"canonicalText":"文學對曰：「竊聞治人之道，防淫佚之原，廣道德之端，抑末利而開仁義，毋示以利，然後教化可興，而風俗可移也。","chunks":[["文學對曰：「竊聞治人之道，防淫佚之原，廣道德之端，抑末利而開仁義，毋示以利，然後教化可興，而風俗可移也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-2_s-2","passageId":"yan-tie-lun_ch-1_p-2","order":2,"canonicalText":"今郡國有鹽、鐵、酒榷，均輸，與民爭利。","chunks":[["今郡國有鹽、鐵、酒榷，均輸，與民爭利。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-2_s-3","passageId":"yan-tie-lun_ch-1_p-2","order":3,"canonicalText":"散敦厚之樸，成貪鄙之化。","chunks":[["散敦厚之樸，成貪鄙之化。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-2_s-4","passageId":"yan-tie-lun_ch-1_p-2","order":4,"canonicalText":"是以百姓就本者寡，趨末者眾。","chunks":[["是以百姓就本者寡，趨末者眾。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-2_s-5","passageId":"yan-tie-lun_ch-1_p-2","order":5,"canonicalText":"夫文繁則質衰，末盛則質虧。","chunks":[["夫文繁則質衰，末盛則質虧。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-2_s-6","passageId":"yan-tie-lun_ch-1_p-2","order":6,"canonicalText":"末修則民淫，本修則民愨。","chunks":[["末修則民淫，本修則民愨。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-2_s-7","passageId":"yan-tie-lun_ch-1_p-2","order":7,"canonicalText":"民愨則財用足，民侈則饑寒生。","chunks":[["民愨則財用足，民侈則饑寒生。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-2_s-8","passageId":"yan-tie-lun_ch-1_p-2","order":8,"canonicalText":"願罷鹽、鐵、酒榷、均輸，所以進本退末，廣利農業，便也。","chunks":[["願罷鹽、鐵、酒榷、均輸，所以進本退末，廣利農業，便也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-2_s-9","passageId":"yan-tie-lun_ch-1_p-2","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-3_s-1","passageId":"yan-tie-lun_ch-1_p-3","order":1,"canonicalText":"大夫曰：「匈奴背叛不臣，數為寇暴於邊鄙，備之則勞中國之士，不備則侵盜不止。","chunks":[["大夫曰：「匈奴背叛不臣，數為寇暴於邊鄙，備之則勞中國之士，不備則侵盜不止。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-3_s-2","passageId":"yan-tie-lun_ch-1_p-3","order":2,"canonicalText":"先帝哀邊人之久患，苦為虜所係獲也，故修障塞。","chunks":[["先帝哀邊人之久患，苦為虜所係獲也，故修障塞。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-3_s-3","passageId":"yan-tie-lun_ch-1_p-3","order":3,"canonicalText":"飭烽燧，屯戍以備之。","chunks":[["飭烽燧，屯戍以備之。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-3_s-4","passageId":"yan-tie-lun_ch-1_p-3","order":4,"canonicalText":"邊用度不足，故興鹽、鐵，設酒榷，置均輸，蕃貨長財，以佐助邊費。","chunks":[["邊用度不足，故興鹽、鐵，設酒榷，置均輸，蕃貨長財，以佐助邊費。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-3_s-5","passageId":"yan-tie-lun_ch-1_p-3","order":5,"canonicalText":"今議者欲罷之，內空府庫之藏，外乏執備之用，使備塞乘城之士饑寒於邊，將何以贍之？","chunks":[["今議者欲罷之，內空府庫之藏，外乏執備之用，使備塞乘城之士饑寒於邊，將何以贍之？","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-3_s-6","passageId":"yan-tie-lun_ch-1_p-3","order":6,"canonicalText":"罷之，不便也。","chunks":[["罷之，不便也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-3_s-7","passageId":"yan-tie-lun_ch-1_p-3","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-4_s-1","passageId":"yan-tie-lun_ch-1_p-4","order":1,"canonicalText":"文學曰：「孔子曰：『有國有家者，不患貧而患不均，不患寡而患不安。","chunks":[["文學曰：「孔子曰：『有國有家者，不患貧而患不均，不患寡而患不安。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-4_s-2","passageId":"yan-tie-lun_ch-1_p-4","order":2,"canonicalText":"』故天子不言多少，諸侯不言利害，大夫不言得喪。","chunks":[["』故天子不言多少，諸侯不言利害，大夫不言得喪。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-4_s-3","passageId":"yan-tie-lun_ch-1_p-4","order":3,"canonicalText":"畜仁義以風之，廣德行以懷之。","chunks":[["畜仁義以風之，廣德行以懷之。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-4_s-4","passageId":"yan-tie-lun_ch-1_p-4","order":4,"canonicalText":"是以近者親附而遠者悅服。","chunks":[["是以近者親附而遠者悅服。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-4_s-5","passageId":"yan-tie-lun_ch-1_p-4","order":5,"canonicalText":"故善克者不戰，善戰者不師，善師者不陣。","chunks":[["故善克者不戰，善戰者不師，善師者不陣。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-4_s-6","passageId":"yan-tie-lun_ch-1_p-4","order":6,"canonicalText":"修之於廟堂，而折衝還師。","chunks":[["修之於廟堂，而折衝還師。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-4_s-7","passageId":"yan-tie-lun_ch-1_p-4","order":7,"canonicalText":"王者行仁政，無敵於天下，惡用費哉？","chunks":[["王者行仁政，無敵於天下，惡用費哉？","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-4_s-8","passageId":"yan-tie-lun_ch-1_p-4","order":8,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-5_s-1","passageId":"yan-tie-lun_ch-1_p-5","order":1,"canonicalText":"大夫曰：「匈奴桀黠，擅恣入塞，犯厲中國，殺伐郡、縣、朔方都尉，甚悖逆不軌，宜誅討之日久矣。","chunks":[["大夫曰：「匈奴桀黠，擅恣入塞，犯厲中國，殺伐郡、縣、朔方都尉，甚悖逆不軌，宜誅討之日久矣。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-5_s-2","passageId":"yan-tie-lun_ch-1_p-5","order":2,"canonicalText":"陛下垂大惠，哀元元之未贍，不忍暴士大夫於原野；","chunks":[["陛下垂大惠，哀元元之未贍，不忍暴士大夫於原野；","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-5_s-3","passageId":"yan-tie-lun_ch-1_p-5","order":3,"canonicalText":"縱難被堅執銳，有北面復匈奴之志，又欲罷鹽、鐵、均輸，擾邊用，損武略，無憂邊之心，於其義未便也。","chunks":[["縱難被堅執銳，有北面復匈奴之志，又欲罷鹽、鐵、均輸，擾邊用，損武略，無憂邊之心，於其義未便也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-5_s-4","passageId":"yan-tie-lun_ch-1_p-5","order":4,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-6_s-1","passageId":"yan-tie-lun_ch-1_p-6","order":1,"canonicalText":"文學曰：「古者，貴以德而賤用兵。","chunks":[["文學曰：「古者，貴以德而賤用兵。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-6_s-2","passageId":"yan-tie-lun_ch-1_p-6","order":2,"canonicalText":"孔子曰：『遠人不服，則修文德以來之。","chunks":[["孔子曰：『遠人不服，則修文德以來之。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-6_s-3","passageId":"yan-tie-lun_ch-1_p-6","order":3,"canonicalText":"既來之，則安之。","chunks":[["既來之，則安之。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-6_s-4","passageId":"yan-tie-lun_ch-1_p-6","order":4,"canonicalText":"』今廢道德而任兵革，興師而伐之，屯戍而備之，暴兵露師，以支久長，轉輸糧食無已，使邊境之士饑寒於外，百姓勞苦於內。","chunks":[["』今廢道德而任兵革，興師而伐之，屯戍而備之，暴兵露師，以支久長，轉輸糧食無已，使邊境之士饑寒於外，百姓勞苦於內。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-6_s-5","passageId":"yan-tie-lun_ch-1_p-6","order":5,"canonicalText":"立鹽、鐵，始張利官以給之，非長策也。","chunks":[["立鹽、鐵，始張利官以給之，非長策也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-6_s-6","passageId":"yan-tie-lun_ch-1_p-6","order":6,"canonicalText":"故以罷之為便也。","chunks":[["故以罷之為便也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-6_s-7","passageId":"yan-tie-lun_ch-1_p-6","order":7,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-7_s-1","passageId":"yan-tie-lun_ch-1_p-7","order":1,"canonicalText":"大夫曰：「古之立國家者，開本末之途，通有無之用，市朝以一其求，致士民，聚萬貨，農商工師各得所欲，交易而退。","chunks":[["大夫曰：「古之立國家者，開本末之途，通有無之用，市朝以一其求，致士民，聚萬貨，農商工師各得所欲，交易而退。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-7_s-2","passageId":"yan-tie-lun_ch-1_p-7","order":2,"canonicalText":"易曰：『通其變，使民不倦。","chunks":[["易曰：『通其變，使民不倦。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-7_s-3","passageId":"yan-tie-lun_ch-1_p-7","order":3,"canonicalText":"』故工不出，則農用乏；","chunks":[["』故工不出，則農用乏；","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-7_s-4","passageId":"yan-tie-lun_ch-1_p-7","order":4,"canonicalText":"商不出，則寶貨絕。","chunks":[["商不出，則寶貨絕。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-7_s-5","passageId":"yan-tie-lun_ch-1_p-7","order":5,"canonicalText":"農用乏，則穀不殖；","chunks":[["農用乏，則穀不殖；","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-7_s-6","passageId":"yan-tie-lun_ch-1_p-7","order":6,"canonicalText":"寶貨絕，則財用匱。","chunks":[["寶貨絕，則財用匱。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-7_s-7","passageId":"yan-tie-lun_ch-1_p-7","order":7,"canonicalText":"故鹽、鐵、均輸，所以通委財而調緩急。","chunks":[["故鹽、鐵、均輸，所以通委財而調緩急。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-7_s-8","passageId":"yan-tie-lun_ch-1_p-7","order":8,"canonicalText":"罷之，不便也。","chunks":[["罷之，不便也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-7_s-9","passageId":"yan-tie-lun_ch-1_p-7","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-8_s-1","passageId":"yan-tie-lun_ch-1_p-8","order":1,"canonicalText":"文學曰：「夫導民以德則民歸厚；","chunks":[["文學曰：「夫導民以德則民歸厚；","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-8_s-2","passageId":"yan-tie-lun_ch-1_p-8","order":2,"canonicalText":"示民以利，則民俗薄。","chunks":[["示民以利，則民俗薄。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-8_s-3","passageId":"yan-tie-lun_ch-1_p-8","order":3,"canonicalText":"俗薄則背義而趨利，趨利則百姓交於道而接於市。","chunks":[["俗薄則背義而趨利，趨利則百姓交於道而接於市。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-8_s-4","passageId":"yan-tie-lun_ch-1_p-8","order":4,"canonicalText":"老子曰：『貧國若有餘。","chunks":[["老子曰：『貧國若有餘。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-8_s-5","passageId":"yan-tie-lun_ch-1_p-8","order":5,"canonicalText":"』非多財也，嗜慾眾而民躁也。","chunks":[["』非多財也，嗜慾眾而民躁也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-8_s-6","passageId":"yan-tie-lun_ch-1_p-8","order":6,"canonicalText":"是以王者崇本退末，以禮義防民欲，實菽粟貨財。","chunks":[["是以王者崇本退末，以禮義防民欲，實菽粟貨財。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-8_s-7","passageId":"yan-tie-lun_ch-1_p-8","order":7,"canonicalText":"市，商不通無用之物，工不作無用之器。","chunks":[["市，商不通無用之物，工不作無用之器。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-8_s-8","passageId":"yan-tie-lun_ch-1_p-8","order":8,"canonicalText":"故商所以通鬱滯，工所以備器械，非治國之本務也。","chunks":[["故商所以通鬱滯，工所以備器械，非治國之本務也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-8_s-9","passageId":"yan-tie-lun_ch-1_p-8","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-9_s-1","passageId":"yan-tie-lun_ch-1_p-9","order":1,"canonicalText":"大夫曰：「管子云：『國有沃野之饒而民不足於食者，器械不備也。","chunks":[["大夫曰：「管子云：『國有沃野之饒而民不足於食者，器械不備也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-9_s-2","passageId":"yan-tie-lun_ch-1_p-9","order":2,"canonicalText":"有山海之貨而民不足於財者，商工不備也。","chunks":[["有山海之貨而民不足於財者，商工不備也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-9_s-3","passageId":"yan-tie-lun_ch-1_p-9","order":3,"canonicalText":"』隴、蜀之丹漆旄羽，荊、揚之皮革骨象，江南之楠梓竹箭，燕、齊之魚鹽旃裘，兗、豫之漆絲絺紵，養生送終之具也，待商而通，待工而成。","chunks":[["』隴、蜀之丹漆旄羽，荊、揚之皮革骨象，江南之楠梓竹箭，燕、齊之魚鹽旃裘，兗、豫之漆絲絺紵，養生送終之具也，待商而通，待工而成。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-9_s-4","passageId":"yan-tie-lun_ch-1_p-9","order":4,"canonicalText":"故聖人作為舟楫之用，以通川谷，服牛駕馬，以達陵陸；","chunks":[["故聖人作為舟楫之用，以通川谷，服牛駕馬，以達陵陸；","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-9_s-5","passageId":"yan-tie-lun_ch-1_p-9","order":5,"canonicalText":"致遠窮深，所以交庶物而便百姓。","chunks":[["致遠窮深，所以交庶物而便百姓。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-9_s-6","passageId":"yan-tie-lun_ch-1_p-9","order":6,"canonicalText":"是以先帝建鐵官以贍農用，開均輸以足民財；","chunks":[["是以先帝建鐵官以贍農用，開均輸以足民財；","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-9_s-7","passageId":"yan-tie-lun_ch-1_p-9","order":7,"canonicalText":"鹽、鐵、均輸，萬民所戴仰而取給者，罷之，不便也。","chunks":[["鹽、鐵、均輸，萬民所戴仰而取給者，罷之，不便也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-9_s-8","passageId":"yan-tie-lun_ch-1_p-9","order":8,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-10_s-1","passageId":"yan-tie-lun_ch-1_p-10","order":1,"canonicalText":"文學曰：「國有沃野之饒而民不足於食者，工商盛而本業荒也；","chunks":[["文學曰：「國有沃野之饒而民不足於食者，工商盛而本業荒也；","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-10_s-2","passageId":"yan-tie-lun_ch-1_p-10","order":2,"canonicalText":"有山海之貨而民不足於財者，不務民用而淫巧眾也。","chunks":[["有山海之貨而民不足於財者，不務民用而淫巧眾也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-10_s-3","passageId":"yan-tie-lun_ch-1_p-10","order":3,"canonicalText":"故川源不能實漏卮，山海不能贍溪壑。","chunks":[["故川源不能實漏卮，山海不能贍溪壑。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-10_s-4","passageId":"yan-tie-lun_ch-1_p-10","order":4,"canonicalText":"是以盤庚萃居，舜藏黃金，高帝禁商賈不得仕宦，所以遏貪鄙之俗，而醇至誠之風也。","chunks":[["是以盤庚萃居，舜藏黃金，高帝禁商賈不得仕宦，所以遏貪鄙之俗，而醇至誠之風也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-10_s-5","passageId":"yan-tie-lun_ch-1_p-10","order":5,"canonicalText":"排困市井，防塞利門，而民猶為非也，況上之為利乎？","chunks":[["排困市井，防塞利門，而民猶為非也，況上之為利乎？","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-10_s-6","passageId":"yan-tie-lun_ch-1_p-10","order":6,"canonicalText":"傳曰：『諸侯好利則大夫鄙，大夫鄙則士貪，士貪則庶人盜。","chunks":[["傳曰：『諸侯好利則大夫鄙，大夫鄙則士貪，士貪則庶人盜。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-10_s-7","passageId":"yan-tie-lun_ch-1_p-10","order":7,"canonicalText":"』是開利孔為民罪梯也。","chunks":[["』是開利孔為民罪梯也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-10_s-8","passageId":"yan-tie-lun_ch-1_p-10","order":8,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-11_s-1","passageId":"yan-tie-lun_ch-1_p-11","order":1,"canonicalText":"大夫曰：「往者，郡國諸侯各以其方物貢輸，往來煩雜，物多苦惡，或不償其費。","chunks":[["大夫曰：「往者，郡國諸侯各以其方物貢輸，往來煩雜，物多苦惡，或不償其費。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-11_s-2","passageId":"yan-tie-lun_ch-1_p-11","order":2,"canonicalText":"故郡國置輸官以相給運，而便遠方之貢，故曰均輸。","chunks":[["故郡國置輸官以相給運，而便遠方之貢，故曰均輸。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-11_s-3","passageId":"yan-tie-lun_ch-1_p-11","order":3,"canonicalText":"開委府於京師，以籠貨物。","chunks":[["開委府於京師，以籠貨物。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-11_s-4","passageId":"yan-tie-lun_ch-1_p-11","order":4,"canonicalText":"賤即買，貴則賣。","chunks":[["賤即買，貴則賣。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-11_s-5","passageId":"yan-tie-lun_ch-1_p-11","order":5,"canonicalText":"是以縣官不失實，商賈無所貿利，故曰平準。","chunks":[["是以縣官不失實，商賈無所貿利，故曰平準。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-11_s-6","passageId":"yan-tie-lun_ch-1_p-11","order":6,"canonicalText":"平準則民不失職，均輸則民齊勞逸。","chunks":[["平準則民不失職，均輸則民齊勞逸。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-11_s-7","passageId":"yan-tie-lun_ch-1_p-11","order":7,"canonicalText":"故平準、均輸，所以平萬物而便百姓，非開利孔而為民罪梯者也。","chunks":[["故平準、均輸，所以平萬物而便百姓，非開利孔而為民罪梯者也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-11_s-8","passageId":"yan-tie-lun_ch-1_p-11","order":8,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-12_s-1","passageId":"yan-tie-lun_ch-1_p-12","order":1,"canonicalText":"文學曰：「古者之賦稅於民也，因其所工，不求所拙。","chunks":[["文學曰：「古者之賦稅於民也，因其所工，不求所拙。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-12_s-2","passageId":"yan-tie-lun_ch-1_p-12","order":2,"canonicalText":"農人納其穫，女工效其功。","chunks":[["農人納其穫，女工效其功。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-12_s-3","passageId":"yan-tie-lun_ch-1_p-12","order":3,"canonicalText":"今釋其所有，責其所無。","chunks":[["今釋其所有，責其所無。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-12_s-4","passageId":"yan-tie-lun_ch-1_p-12","order":4,"canonicalText":"百姓賤賣貨物，以便上求。","chunks":[["百姓賤賣貨物，以便上求。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-12_s-5","passageId":"yan-tie-lun_ch-1_p-12","order":5,"canonicalText":"間者，郡國或令民作布絮，吏恣留難，與之為市。","chunks":[["間者，郡國或令民作布絮，吏恣留難，與之為市。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-12_s-6","passageId":"yan-tie-lun_ch-1_p-12","order":6,"canonicalText":"吏之所入，非獨齊、阿之縑，蜀、漢之布也，亦民間之所為耳。","chunks":[["吏之所入，非獨齊、阿之縑，蜀、漢之布也，亦民間之所為耳。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-12_s-7","passageId":"yan-tie-lun_ch-1_p-12","order":7,"canonicalText":"行姦賣平，農民重苦，女工再稅，未見輸之均也。","chunks":[["行姦賣平，農民重苦，女工再稅，未見輸之均也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-12_s-8","passageId":"yan-tie-lun_ch-1_p-12","order":8,"canonicalText":"縣官猥發，闔門擅市，則萬物并收。","chunks":[["縣官猥發，闔門擅市，則萬物并收。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-12_s-9","passageId":"yan-tie-lun_ch-1_p-12","order":9,"canonicalText":"萬物并收，則物騰躍。","chunks":[["萬物并收，則物騰躍。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-12_s-10","passageId":"yan-tie-lun_ch-1_p-12","order":10,"canonicalText":"騰躍，則商賈侔利。","chunks":[["騰躍，則商賈侔利。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-12_s-11","passageId":"yan-tie-lun_ch-1_p-12","order":11,"canonicalText":"自市，則吏容姦。","chunks":[["自市，則吏容姦。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-12_s-12","passageId":"yan-tie-lun_ch-1_p-12","order":12,"canonicalText":"豪吏富商積貨儲物以待其急，輕賈姦吏收賤以取貴，未見準之平也。","chunks":[["豪吏富商積貨儲物以待其急，輕賈姦吏收賤以取貴，未見準之平也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-12_s-13","passageId":"yan-tie-lun_ch-1_p-12","order":13,"canonicalText":"蓋古之均輸，所以齊勞逸而便貢輸，非以為利而賈萬物也。","chunks":[["蓋古之均輸，所以齊勞逸而便貢輸，非以為利而賈萬物也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-1_p-12_s-14","passageId":"yan-tie-lun_ch-1_p-12","order":14,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-1_s-1","passageId":"yan-tie-lun_ch-2_p-1","order":1,"canonicalText":"大夫曰：「王者塞天財，禁關市，執準守時，以輕重御民。","chunks":[["大夫曰：「王者塞天財，禁關市，執準守時，以輕重御民。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-1_s-2","passageId":"yan-tie-lun_ch-2_p-1","order":2,"canonicalText":"豐年歲登，則儲積以備乏絕；","chunks":[["豐年歲登，則儲積以備乏絕；","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-1_s-3","passageId":"yan-tie-lun_ch-2_p-1","order":3,"canonicalText":"凶年惡歲，則行幣物；","chunks":[["凶年惡歲，則行幣物；","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-1_s-4","passageId":"yan-tie-lun_ch-2_p-1","order":4,"canonicalText":"流有餘而調不足也。","chunks":[["流有餘而調不足也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-1_s-5","passageId":"yan-tie-lun_ch-2_p-1","order":5,"canonicalText":"昔禹水湯旱，百姓匱乏，或相假以接衣食。","chunks":[["昔禹水湯旱，百姓匱乏，或相假以接衣食。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-1_s-6","passageId":"yan-tie-lun_ch-2_p-1","order":6,"canonicalText":"禹以歷山之金，湯以莊山之銅，鑄幣以贖其民，而天下稱仁。","chunks":[["禹以歷山之金，湯以莊山之銅，鑄幣以贖其民，而天下稱仁。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-1_s-7","passageId":"yan-tie-lun_ch-2_p-1","order":7,"canonicalText":"往者財用不足，戰士或不得祿，而山東被災，齊、趙大饑，賴均輸之畜，倉廩之積，戰士以奉，饑民以賑。","chunks":[["往者財用不足，戰士或不得祿，而山東被災，齊、趙大饑，賴均輸之畜，倉廩之積，戰士以奉，饑民以賑。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-1_s-8","passageId":"yan-tie-lun_ch-2_p-1","order":8,"canonicalText":"故均輸之物，府庫之財，非所以賈萬民而專奉兵師之用，亦所以賑困乏而備水旱之災也。","chunks":[["故均輸之物，府庫之財，非所以賈萬民而專奉兵師之用，亦所以賑困乏而備水旱之災也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-1_s-9","passageId":"yan-tie-lun_ch-2_p-1","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-2_s-1","passageId":"yan-tie-lun_ch-2_p-2","order":1,"canonicalText":"文學曰：「古者，十一而稅，澤梁以時入而無禁，黎民咸被南畝而不失其務。","chunks":[["文學曰：「古者，十一而稅，澤梁以時入而無禁，黎民咸被南畝而不失其務。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-2_s-2","passageId":"yan-tie-lun_ch-2_p-2","order":2,"canonicalText":"故三年耕而餘一年之蓄，九年耕有三年之蓄。","chunks":[["故三年耕而餘一年之蓄，九年耕有三年之蓄。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-2_s-3","passageId":"yan-tie-lun_ch-2_p-2","order":3,"canonicalText":"此禹、湯所以備水旱而安百姓也。","chunks":[["此禹、湯所以備水旱而安百姓也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-2_s-4","passageId":"yan-tie-lun_ch-2_p-2","order":4,"canonicalText":"草萊不闢，田疇不治，雖擅山海之財，通百末之利，猶不能贍也。","chunks":[["草萊不闢，田疇不治，雖擅山海之財，通百末之利，猶不能贍也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-2_s-5","passageId":"yan-tie-lun_ch-2_p-2","order":5,"canonicalText":"是以古者尚力務本而種樹繁，躬耕趣時而衣食足，雖累凶年而人不病也。","chunks":[["是以古者尚力務本而種樹繁，躬耕趣時而衣食足，雖累凶年而人不病也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-2_s-6","passageId":"yan-tie-lun_ch-2_p-2","order":6,"canonicalText":"故衣食者民之本，稼穡者民之務也。","chunks":[["故衣食者民之本，稼穡者民之務也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-2_s-7","passageId":"yan-tie-lun_ch-2_p-2","order":7,"canonicalText":"二者修，則國富而民安也。","chunks":[["二者修，則國富而民安也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-2_s-8","passageId":"yan-tie-lun_ch-2_p-2","order":8,"canonicalText":"《》云：『』也。","chunks":[["《》云：『』也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-2_s-9","passageId":"yan-tie-lun_ch-2_p-2","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-3_s-1","passageId":"yan-tie-lun_ch-2_p-3","order":1,"canonicalText":"大夫曰：「賢聖治家非一寶，富國非一道。","chunks":[["大夫曰：「賢聖治家非一寶，富國非一道。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-3_s-2","passageId":"yan-tie-lun_ch-2_p-3","order":2,"canonicalText":"昔管仲以權譎霸，而紀氏以強本亡。","chunks":[["昔管仲以權譎霸，而紀氏以強本亡。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-3_s-3","passageId":"yan-tie-lun_ch-2_p-3","order":3,"canonicalText":"使治家養生必於農，則舜不甄陶而伊尹不為庖。","chunks":[["使治家養生必於農，則舜不甄陶而伊尹不為庖。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-3_s-4","passageId":"yan-tie-lun_ch-2_p-3","order":4,"canonicalText":"故善為國者，天下之下我高，天下之輕我重。","chunks":[["故善為國者，天下之下我高，天下之輕我重。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-3_s-5","passageId":"yan-tie-lun_ch-2_p-3","order":5,"canonicalText":"以末易其本，以虛蕩其實。","chunks":[["以末易其本，以虛蕩其實。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-3_s-6","passageId":"yan-tie-lun_ch-2_p-3","order":6,"canonicalText":"今山澤之財，均輸之藏，所以御輕重而役諸侯也。","chunks":[["今山澤之財，均輸之藏，所以御輕重而役諸侯也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-3_s-7","passageId":"yan-tie-lun_ch-2_p-3","order":7,"canonicalText":"汝、漢之金，纖微之貢，所以誘外國而釣胡、羌之寶也。","chunks":[["汝、漢之金，纖微之貢，所以誘外國而釣胡、羌之寶也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-3_s-8","passageId":"yan-tie-lun_ch-2_p-3","order":8,"canonicalText":"夫中國一端之縵，得匈奴累金之物，而損敵國之用。","chunks":[["夫中國一端之縵，得匈奴累金之物，而損敵國之用。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-3_s-9","passageId":"yan-tie-lun_ch-2_p-3","order":9,"canonicalText":"是以騾驢馲駝，銜尾入塞，驒騱騵馬，盡為我畜，鼲貂狐貉，采旃文罽，充於內府，而璧玉珊瑚琉璃，咸為國之寶。","chunks":[["是以騾驢馲駝，銜尾入塞，驒騱騵馬，盡為我畜，鼲貂狐貉，采旃文罽，充於內府，而璧玉珊瑚琉璃，咸為國之寶。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-3_s-10","passageId":"yan-tie-lun_ch-2_p-3","order":10,"canonicalText":"是則外國之物內流，而利不外泄也。","chunks":[["是則外國之物內流，而利不外泄也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-3_s-11","passageId":"yan-tie-lun_ch-2_p-3","order":11,"canonicalText":"異物內流則國用饒，利不外泄則民用給矣。","chunks":[["異物內流則國用饒，利不外泄則民用給矣。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-3_s-12","passageId":"yan-tie-lun_ch-2_p-3","order":12,"canonicalText":"《》曰：『』」","chunks":[["《》曰：『』」","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-4_s-1","passageId":"yan-tie-lun_ch-2_p-4","order":1,"canonicalText":"文學曰：「古者，商通物而不豫，工致牢而不偽。","chunks":[["文學曰：「古者，商通物而不豫，工致牢而不偽。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-4_s-2","passageId":"yan-tie-lun_ch-2_p-4","order":2,"canonicalText":"故君子耕稼田魚，其實一也。","chunks":[["故君子耕稼田魚，其實一也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-4_s-3","passageId":"yan-tie-lun_ch-2_p-4","order":3,"canonicalText":"商則長詐，工則飾罵，內懷闚窬而心不怍，是以薄夫欺而敦夫薄。","chunks":[["商則長詐，工則飾罵，內懷闚窬而心不怍，是以薄夫欺而敦夫薄。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-4_s-4","passageId":"yan-tie-lun_ch-2_p-4","order":4,"canonicalText":"昔桀女樂充宮室，文繡衣裳，故伊尹高逝遊薄，而女樂終廢其國。","chunks":[["昔桀女樂充宮室，文繡衣裳，故伊尹高逝遊薄，而女樂終廢其國。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-4_s-5","passageId":"yan-tie-lun_ch-2_p-4","order":5,"canonicalText":"今騾驢之用，不中牛馬之功，鼲貂旃罽，不益錦綈之實。","chunks":[["今騾驢之用，不中牛馬之功，鼲貂旃罽，不益錦綈之實。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-4_s-6","passageId":"yan-tie-lun_ch-2_p-4","order":6,"canonicalText":"美玉珊瑚出於昆山，珠璣犀象出於桂林，此距漢萬有餘里。","chunks":[["美玉珊瑚出於昆山，珠璣犀象出於桂林，此距漢萬有餘里。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-4_s-7","passageId":"yan-tie-lun_ch-2_p-4","order":7,"canonicalText":"計耕桑之功，資財之費，是一物而售百倍其價也，一揖而中萬鍾之粟也。","chunks":[["計耕桑之功，資財之費，是一物而售百倍其價也，一揖而中萬鍾之粟也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-4_s-8","passageId":"yan-tie-lun_ch-2_p-4","order":8,"canonicalText":"夫上好珍怪，則淫服下流，貴遠方之物，則貨財外充。","chunks":[["夫上好珍怪，則淫服下流，貴遠方之物，則貨財外充。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-4_s-9","passageId":"yan-tie-lun_ch-2_p-4","order":9,"canonicalText":"是以王者不珍無用以節其民，不愛奇貨以富其國。","chunks":[["是以王者不珍無用以節其民，不愛奇貨以富其國。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-4_s-10","passageId":"yan-tie-lun_ch-2_p-4","order":10,"canonicalText":"故理民之道，在於節用尚本，分土井田而已。","chunks":[["故理民之道，在於節用尚本，分土井田而已。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-4_s-11","passageId":"yan-tie-lun_ch-2_p-4","order":11,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-5_s-1","passageId":"yan-tie-lun_ch-2_p-5","order":1,"canonicalText":"大夫曰：「自京師東西南北，歷山川，經郡國，諸殷富大都，無非街衢五通，商賈之所湊，萬物之所殖者。","chunks":[["大夫曰：「自京師東西南北，歷山川，經郡國，諸殷富大都，無非街衢五通，商賈之所湊，萬物之所殖者。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-5_s-2","passageId":"yan-tie-lun_ch-2_p-5","order":2,"canonicalText":"故聖人因天時，智者因地財，上士取諸人，中士勞其形。","chunks":[["故聖人因天時，智者因地財，上士取諸人，中士勞其形。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-5_s-3","passageId":"yan-tie-lun_ch-2_p-5","order":3,"canonicalText":"長沮、桀溺，無百金之積，蹠蹻之徒，無猗頓之富，宛、周、齊、魯，商遍天下。","chunks":[["長沮、桀溺，無百金之積，蹠蹻之徒，無猗頓之富，宛、周、齊、魯，商遍天下。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-5_s-4","passageId":"yan-tie-lun_ch-2_p-5","order":4,"canonicalText":"故乃商賈之富，或累萬金，追利乘羡之所致也。","chunks":[["故乃商賈之富，或累萬金，追利乘羡之所致也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-5_s-5","passageId":"yan-tie-lun_ch-2_p-5","order":5,"canonicalText":"富國何必用本農，足民何必井田也？","chunks":[["富國何必用本農，足民何必井田也？","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-5_s-6","passageId":"yan-tie-lun_ch-2_p-5","order":6,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-6_s-1","passageId":"yan-tie-lun_ch-2_p-6","order":1,"canonicalText":"文學曰：「洪水滔天，而有禹之績，河水泛濫，而有宣房之功。","chunks":[["文學曰：「洪水滔天，而有禹之績，河水泛濫，而有宣房之功。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-6_s-2","passageId":"yan-tie-lun_ch-2_p-6","order":2,"canonicalText":"商紂暴虐，而有孟津之謀，天下煩擾，而有乘羡之富。","chunks":[["商紂暴虐，而有孟津之謀，天下煩擾，而有乘羡之富。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-6_s-3","passageId":"yan-tie-lun_ch-2_p-6","order":3,"canonicalText":"夫上古至治，民樸而貴本、安愉而寡求。","chunks":[["夫上古至治，民樸而貴本、安愉而寡求。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-6_s-4","passageId":"yan-tie-lun_ch-2_p-6","order":4,"canonicalText":"當此之時，道路罕行，市朝生草。","chunks":[["當此之時，道路罕行，市朝生草。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-6_s-5","passageId":"yan-tie-lun_ch-2_p-6","order":5,"canonicalText":"故耕不強者無以充虛，織不強者無以掩形。","chunks":[["故耕不強者無以充虛，織不強者無以掩形。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-6_s-6","passageId":"yan-tie-lun_ch-2_p-6","order":6,"canonicalText":"雖有湊會之要，陶、宛之術，無所施其巧。","chunks":[["雖有湊會之要，陶、宛之術，無所施其巧。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-6_s-7","passageId":"yan-tie-lun_ch-2_p-6","order":7,"canonicalText":"自古及今，不施而得報，不勞而有功者，未之有也。","chunks":[["自古及今，不施而得報，不勞而有功者，未之有也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-2_p-6_s-8","passageId":"yan-tie-lun_ch-2_p-6","order":8,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-1_s-1","passageId":"yan-tie-lun_ch-3_p-1","order":1,"canonicalText":"大夫曰：「燕之涿、薊，趙之邯鄲，魏之溫軹，韓之滎陽，齊之臨淄，楚之宛、陳，鄭之陽翟，三川之二周，富冠海內，皆為天下名都，非有助之耕其野而田其地者也，居五諸之衝，跨街衢之路也。","chunks":[["大夫曰：「燕之涿、薊，趙之邯鄲，魏之溫軹，韓之滎陽，齊之臨淄，楚之宛、陳，鄭之陽翟，三川之二周，富冠海內，皆為天下名都，非有助之耕其野而田其地者也，居五諸之衝，跨街衢之路也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-1_s-2","passageId":"yan-tie-lun_ch-3_p-1","order":2,"canonicalText":"故物豐者民衍，宅近市者家富。","chunks":[["故物豐者民衍，宅近市者家富。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-1_s-3","passageId":"yan-tie-lun_ch-3_p-1","order":3,"canonicalText":"富在術數，不在勞身；","chunks":[["富在術數，不在勞身；","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-1_s-4","passageId":"yan-tie-lun_ch-3_p-1","order":4,"canonicalText":"利在勢居，不在力耕也。","chunks":[["利在勢居，不在力耕也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-2_s-1","passageId":"yan-tie-lun_ch-3_p-2","order":1,"canonicalText":"文學曰：「荊、揚南有桂林之饒，內有江、湖之利，左陵陽之金，右蜀、漢之材，伐木而樹穀，燔萊而播粟，火耕而水耨，地廣而饒財；","chunks":[["文學曰：「荊、揚南有桂林之饒，內有江、湖之利，左陵陽之金，右蜀、漢之材，伐木而樹穀，燔萊而播粟，火耕而水耨，地廣而饒財；","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-2_s-2","passageId":"yan-tie-lun_ch-3_p-2","order":2,"canonicalText":"然民鮆窳偷生，好衣甘食，雖白屋草廬，歌謳鼓琴，日給月單，朝歌暮戚。","chunks":[["然民鮆窳偷生，好衣甘食，雖白屋草廬，歌謳鼓琴，日給月單，朝歌暮戚。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-2_s-3","passageId":"yan-tie-lun_ch-3_p-2","order":3,"canonicalText":"趙、中山帶大河，纂四通神衢，當天下之蹊，商賈錯於路，諸侯交於道；","chunks":[["趙、中山帶大河，纂四通神衢，當天下之蹊，商賈錯於路，諸侯交於道；","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-2_s-4","passageId":"yan-tie-lun_ch-3_p-2","order":4,"canonicalText":"然民淫好末，侈靡而不務本，田疇不脩，男女矜飾，家無斗筲，鳴琴在室。","chunks":[["然民淫好末，侈靡而不務本，田疇不脩，男女矜飾，家無斗筲，鳴琴在室。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-2_s-5","passageId":"yan-tie-lun_ch-3_p-2","order":5,"canonicalText":"是以楚、趙之民，均貧而寡富。","chunks":[["是以楚、趙之民，均貧而寡富。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-2_s-6","passageId":"yan-tie-lun_ch-3_p-2","order":6,"canonicalText":"宋、衛、韓、梁，好本稼穡，編戶齊民，無不家衍人給。","chunks":[["宋、衛、韓、梁，好本稼穡，編戶齊民，無不家衍人給。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-2_s-7","passageId":"yan-tie-lun_ch-3_p-2","order":7,"canonicalText":"故利在自惜，不在勢居街衢；","chunks":[["故利在自惜，不在勢居街衢；","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-2_s-8","passageId":"yan-tie-lun_ch-3_p-2","order":8,"canonicalText":"富在儉力趣時，不在歲司羽鳩也。","chunks":[["富在儉力趣時，不在歲司羽鳩也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-2_s-9","passageId":"yan-tie-lun_ch-3_p-2","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-3_s-1","passageId":"yan-tie-lun_ch-3_p-3","order":1,"canonicalText":"大夫曰：「五行：東方木，而丹、章有金銅之山；","chunks":[["大夫曰：「五行：東方木，而丹、章有金銅之山；","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-3_s-2","passageId":"yan-tie-lun_ch-3_p-3","order":2,"canonicalText":"南方火，而交趾有大海之川；","chunks":[["南方火，而交趾有大海之川；","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-3_s-3","passageId":"yan-tie-lun_ch-3_p-3","order":3,"canonicalText":"西方金，而蜀、隴有名材之林；","chunks":[["西方金，而蜀、隴有名材之林；","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-3_s-4","passageId":"yan-tie-lun_ch-3_p-3","order":4,"canonicalText":"北方水，而幽都有積沙之地。","chunks":[["北方水，而幽都有積沙之地。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-3_s-5","passageId":"yan-tie-lun_ch-3_p-3","order":5,"canonicalText":"此天地所以均有無而通萬物也。","chunks":[["此天地所以均有無而通萬物也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-3_s-6","passageId":"yan-tie-lun_ch-3_p-3","order":6,"canonicalText":"今吳、越之竹，隋、唐之材，不可勝用，而曹、衛、梁、宋，采棺轉尸；","chunks":[["今吳、越之竹，隋、唐之材，不可勝用，而曹、衛、梁、宋，采棺轉尸；","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-3_s-7","passageId":"yan-tie-lun_ch-3_p-3","order":7,"canonicalText":"江、湖之魚，萊、黃之鮐，不可勝食，而鄒、魯、周、韓，藜藿蔬食。","chunks":[["江、湖之魚，萊、黃之鮐，不可勝食，而鄒、魯、周、韓，藜藿蔬食。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-3_s-8","passageId":"yan-tie-lun_ch-3_p-3","order":8,"canonicalText":"天地之利無不贍，而山海之貨無不富也；","chunks":[["天地之利無不贍，而山海之貨無不富也；","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-3_s-9","passageId":"yan-tie-lun_ch-3_p-3","order":9,"canonicalText":"然百姓匱乏，財用不足，多寡不調，而天下財不散也。","chunks":[["然百姓匱乏，財用不足，多寡不調，而天下財不散也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-3_s-10","passageId":"yan-tie-lun_ch-3_p-3","order":10,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-4_s-1","passageId":"yan-tie-lun_ch-3_p-4","order":1,"canonicalText":"文學曰：「古者，采椽不斲，茅茨不翦，衣布褐，飯土硎，鑄金為鉏，埏埴為器，工不造奇巧，世不寶不可衣食之物，各安其居，樂其俗，甘其食，便其器。","chunks":[["文學曰：「古者，采椽不斲，茅茨不翦，衣布褐，飯土硎，鑄金為鉏，埏埴為器，工不造奇巧，世不寶不可衣食之物，各安其居，樂其俗，甘其食，便其器。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-4_s-2","passageId":"yan-tie-lun_ch-3_p-4","order":2,"canonicalText":"是以遠方之物不交，而崑山之玉不至。","chunks":[["是以遠方之物不交，而崑山之玉不至。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-4_s-3","passageId":"yan-tie-lun_ch-3_p-4","order":3,"canonicalText":"今世俗壞而競於淫靡，女極纖微，工極技巧，雕素樸而尚珍怪，鑽山石而求金銀，沒深淵求珠璣，設機陷求犀象，張網羅求翡翠，求蠻、貉之物以眩中國，徙邛、筰之貨，致之東海，交萬里之財，曠日費功，無益於用。","chunks":[["今世俗壞而競於淫靡，女極纖微，工極技巧，雕素樸而尚珍怪，鑽山石而求金銀，沒深淵求珠璣，設機陷求犀象，張網羅求翡翠，求蠻、貉之物以眩中國，徙邛、筰之貨，致之東海，交萬里之財，曠日費功，無益於用。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-4_s-4","passageId":"yan-tie-lun_ch-3_p-4","order":4,"canonicalText":"是以褐夫匹婦，勞疲力屈，而衣食不足也。","chunks":[["是以褐夫匹婦，勞疲力屈，而衣食不足也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-4_s-5","passageId":"yan-tie-lun_ch-3_p-4","order":5,"canonicalText":"故王者禁溢利，節漏費。","chunks":[["故王者禁溢利，節漏費。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-4_s-6","passageId":"yan-tie-lun_ch-3_p-4","order":6,"canonicalText":"溢利禁則反本，漏費節則民用給。","chunks":[["溢利禁則反本，漏費節則民用給。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-4_s-7","passageId":"yan-tie-lun_ch-3_p-4","order":7,"canonicalText":"是以生無乏資，死無轉尸也。","chunks":[["是以生無乏資，死無轉尸也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-4_s-8","passageId":"yan-tie-lun_ch-3_p-4","order":8,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-5_s-1","passageId":"yan-tie-lun_ch-3_p-5","order":1,"canonicalText":"大夫曰：「古者，宮室有度，輿服以庸；","chunks":[["大夫曰：「古者，宮室有度，輿服以庸；","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-5_s-2","passageId":"yan-tie-lun_ch-3_p-5","order":2,"canonicalText":"采椽茅茨，非先王之制也。","chunks":[["采椽茅茨，非先王之制也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-5_s-3","passageId":"yan-tie-lun_ch-3_p-5","order":3,"canonicalText":"君子節奢刺儉，儉則固。","chunks":[["君子節奢刺儉，儉則固。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-5_s-4","passageId":"yan-tie-lun_ch-3_p-5","order":4,"canonicalText":"昔孫叔敖相楚，妻不衣帛，馬不秣粟。","chunks":[["昔孫叔敖相楚，妻不衣帛，馬不秣粟。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-5_s-5","passageId":"yan-tie-lun_ch-3_p-5","order":5,"canonicalText":"孔子曰：『不可，大儉極下。","chunks":[["孔子曰：『不可，大儉極下。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-5_s-6","passageId":"yan-tie-lun_ch-3_p-5","order":6,"canonicalText":"』此蟋蟀所為作也。","chunks":[["』此蟋蟀所為作也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-5_s-7","passageId":"yan-tie-lun_ch-3_p-5","order":7,"canonicalText":"管子曰：『不飾宮室，則材木不可勝用，不充庖廚，則禽獸不損其壽。","chunks":[["管子曰：『不飾宮室，則材木不可勝用，不充庖廚，則禽獸不損其壽。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-5_s-8","passageId":"yan-tie-lun_ch-3_p-5","order":8,"canonicalText":"無末利，則本業無所出，無黼黻，則女工不施。","chunks":[["無末利，則本業無所出，無黼黻，則女工不施。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-5_s-9","passageId":"yan-tie-lun_ch-3_p-5","order":9,"canonicalText":"』故工商梓匠，邦國之用，器械之備也。","chunks":[["』故工商梓匠，邦國之用，器械之備也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-5_s-10","passageId":"yan-tie-lun_ch-3_p-5","order":10,"canonicalText":"自古有之，非獨於此。","chunks":[["自古有之，非獨於此。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-5_s-11","passageId":"yan-tie-lun_ch-3_p-5","order":11,"canonicalText":"弦高販牛於周，五羖賃車入秦，公輸子以規矩，歐冶以鎔鑄。","chunks":[["弦高販牛於周，五羖賃車入秦，公輸子以規矩，歐冶以鎔鑄。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-5_s-12","passageId":"yan-tie-lun_ch-3_p-5","order":12,"canonicalText":"語曰：『百工居肆，以致其事。","chunks":[["語曰：『百工居肆，以致其事。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-5_s-13","passageId":"yan-tie-lun_ch-3_p-5","order":13,"canonicalText":"』農商交易，以利本末。","chunks":[["』農商交易，以利本末。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-5_s-14","passageId":"yan-tie-lun_ch-3_p-5","order":14,"canonicalText":"山居澤處，蓬蒿堯埆，財物流通，有以均之。","chunks":[["山居澤處，蓬蒿堯埆，財物流通，有以均之。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-5_s-15","passageId":"yan-tie-lun_ch-3_p-5","order":15,"canonicalText":"是以多者不獨衍，少者不獨饉。","chunks":[["是以多者不獨衍，少者不獨饉。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-5_s-16","passageId":"yan-tie-lun_ch-3_p-5","order":16,"canonicalText":"若各居其處，食其食，則是橘柚不鬻，朐鹵之鹽不出，旃罽不市，而吳、唐之材不用也。","chunks":[["若各居其處，食其食，則是橘柚不鬻，朐鹵之鹽不出，旃罽不市，而吳、唐之材不用也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-5_s-17","passageId":"yan-tie-lun_ch-3_p-5","order":17,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-6_s-1","passageId":"yan-tie-lun_ch-3_p-6","order":1,"canonicalText":"文學曰：「孟子云：『不違農時，穀不可勝食。","chunks":[["文學曰：「孟子云：『不違農時，穀不可勝食。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-6_s-2","passageId":"yan-tie-lun_ch-3_p-6","order":2,"canonicalText":"蠶麻以時，布帛不可勝衣也。","chunks":[["蠶麻以時，布帛不可勝衣也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-6_s-3","passageId":"yan-tie-lun_ch-3_p-6","order":3,"canonicalText":"斧斤以時，材木不可勝用。","chunks":[["斧斤以時，材木不可勝用。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-6_s-4","passageId":"yan-tie-lun_ch-3_p-6","order":4,"canonicalText":"田漁以時，魚肉不可勝食。","chunks":[["田漁以時，魚肉不可勝食。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-6_s-5","passageId":"yan-tie-lun_ch-3_p-6","order":5,"canonicalText":"』若則飾宮室，增臺榭，梓匠斲巨為小，以圓為方，上成雲氣，下成山林，則材木不足用也。","chunks":[["』若則飾宮室，增臺榭，梓匠斲巨為小，以圓為方，上成雲氣，下成山林，則材木不足用也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-6_s-6","passageId":"yan-tie-lun_ch-3_p-6","order":6,"canonicalText":"男子去本為末，雕文刻鏤，以象禽獸，窮物究變，則穀不足食也。","chunks":[["男子去本為末，雕文刻鏤，以象禽獸，窮物究變，則穀不足食也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-6_s-7","passageId":"yan-tie-lun_ch-3_p-6","order":7,"canonicalText":"婦女飾微治細，以成文章，極伎盡巧，則絲布不足衣也。","chunks":[["婦女飾微治細，以成文章，極伎盡巧，則絲布不足衣也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-6_s-8","passageId":"yan-tie-lun_ch-3_p-6","order":8,"canonicalText":"庖宰烹殺胎卵，煎炙齊和，窮極五味，則魚肉不足食也。","chunks":[["庖宰烹殺胎卵，煎炙齊和，窮極五味，則魚肉不足食也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-6_s-9","passageId":"yan-tie-lun_ch-3_p-6","order":9,"canonicalText":"當今世，非患禽獸不損，材木不勝，患僭侈之無窮也；","chunks":[["當今世，非患禽獸不損，材木不勝，患僭侈之無窮也；","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-6_s-10","passageId":"yan-tie-lun_ch-3_p-6","order":10,"canonicalText":"非患無旃罽橘柚，患無狹廬糠糟也。","chunks":[["非患無旃罽橘柚，患無狹廬糠糟也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-3_p-6_s-11","passageId":"yan-tie-lun_ch-3_p-6","order":11,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-1_s-1","passageId":"yan-tie-lun_ch-4_p-1","order":1,"canonicalText":"大夫曰：「交幣通施，民事不及，物有所并也。","chunks":[["大夫曰：「交幣通施，民事不及，物有所并也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-1_s-2","passageId":"yan-tie-lun_ch-4_p-1","order":2,"canonicalText":"計本量委，民有饑者，穀有所藏也。","chunks":[["計本量委，民有饑者，穀有所藏也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-1_s-3","passageId":"yan-tie-lun_ch-4_p-1","order":3,"canonicalText":"智者有百人之功，愚者有不更本之事。","chunks":[["智者有百人之功，愚者有不更本之事。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-1_s-4","passageId":"yan-tie-lun_ch-4_p-1","order":4,"canonicalText":"人君不調，民有相萬之富也。","chunks":[["人君不調，民有相萬之富也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-1_s-5","passageId":"yan-tie-lun_ch-4_p-1","order":5,"canonicalText":"此其所以或儲百年之餘，或不厭糟糠也。","chunks":[["此其所以或儲百年之餘，或不厭糟糠也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-1_s-6","passageId":"yan-tie-lun_ch-4_p-1","order":6,"canonicalText":"民大富，則不可以祿使也；","chunks":[["民大富，則不可以祿使也；","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-1_s-7","passageId":"yan-tie-lun_ch-4_p-1","order":7,"canonicalText":"大彊，則不可以罰威也。","chunks":[["大彊，則不可以罰威也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-1_s-8","passageId":"yan-tie-lun_ch-4_p-1","order":8,"canonicalText":"非散聚均利者不齊。","chunks":[["非散聚均利者不齊。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-1_s-9","passageId":"yan-tie-lun_ch-4_p-1","order":9,"canonicalText":"故人主積其食，守其用，制其有餘，調其不足，禁溢羡，厄利塗，然後百姓可家給人足也。","chunks":[["故人主積其食，守其用，制其有餘，調其不足，禁溢羡，厄利塗，然後百姓可家給人足也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-1_s-10","passageId":"yan-tie-lun_ch-4_p-1","order":10,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-2_s-1","passageId":"yan-tie-lun_ch-4_p-2","order":1,"canonicalText":"文學曰：「古者，貴德而賤利，重義而輕財。","chunks":[["文學曰：「古者，貴德而賤利，重義而輕財。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-2_s-2","passageId":"yan-tie-lun_ch-4_p-2","order":2,"canonicalText":"三王之時，迭盛迭衰。","chunks":[["三王之時，迭盛迭衰。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-2_s-3","passageId":"yan-tie-lun_ch-4_p-2","order":3,"canonicalText":"衰則扶之，傾則定之。","chunks":[["衰則扶之，傾則定之。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-2_s-4","passageId":"yan-tie-lun_ch-4_p-2","order":4,"canonicalText":"是以夏忠、殷敬、周文，庠序之教，恭讓之禮，粲然可得而觀也。","chunks":[["是以夏忠、殷敬、周文，庠序之教，恭讓之禮，粲然可得而觀也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-2_s-5","passageId":"yan-tie-lun_ch-4_p-2","order":5,"canonicalText":"及其後，禮義弛崩，風俗滅息，故自食祿之君子，違於義而競於財，大小相吞，淚轉相傾。","chunks":[["及其後，禮義弛崩，風俗滅息，故自食祿之君子，違於義而競於財，大小相吞，淚轉相傾。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-2_s-6","passageId":"yan-tie-lun_ch-4_p-2","order":6,"canonicalText":"此所以或儲百年之餘，或無以充虛蔽形也。","chunks":[["此所以或儲百年之餘，或無以充虛蔽形也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-2_s-7","passageId":"yan-tie-lun_ch-4_p-2","order":7,"canonicalText":"古之仕者不穡，田者不漁，抱關擊柝，皆有常秩，不得兼利盡物。","chunks":[["古之仕者不穡，田者不漁，抱關擊柝，皆有常秩，不得兼利盡物。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-2_s-8","passageId":"yan-tie-lun_ch-4_p-2","order":8,"canonicalText":"如此，則愚智同功，不相傾也。","chunks":[["如此，則愚智同功，不相傾也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-2_s-9","passageId":"yan-tie-lun_ch-4_p-2","order":9,"canonicalText":"《》云：『』言不盡物也。","chunks":[["《》云：『』言不盡物也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-2_s-10","passageId":"yan-tie-lun_ch-4_p-2","order":10,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-3_s-1","passageId":"yan-tie-lun_ch-4_p-3","order":1,"canonicalText":"大夫曰：「湯、文繼衰，漢興乘弊。","chunks":[["大夫曰：「湯、文繼衰，漢興乘弊。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-3_s-2","passageId":"yan-tie-lun_ch-4_p-3","order":2,"canonicalText":"一質一文，非苟易常也。","chunks":[["一質一文，非苟易常也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-3_s-3","passageId":"yan-tie-lun_ch-4_p-3","order":3,"canonicalText":"俗弊更法，非務變古也，亦所以救失扶衰也。","chunks":[["俗弊更法，非務變古也，亦所以救失扶衰也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-3_s-4","passageId":"yan-tie-lun_ch-4_p-3","order":4,"canonicalText":"故教與俗改，弊與世易。","chunks":[["故教與俗改，弊與世易。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-3_s-5","passageId":"yan-tie-lun_ch-4_p-3","order":5,"canonicalText":"夏后以玄貝，周人以紫石，後世或金錢刀布。","chunks":[["夏后以玄貝，周人以紫石，後世或金錢刀布。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-3_s-6","passageId":"yan-tie-lun_ch-4_p-3","order":6,"canonicalText":"物極而衰，終始之運也。","chunks":[["物極而衰，終始之運也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-3_s-7","passageId":"yan-tie-lun_ch-4_p-3","order":7,"canonicalText":"故山澤無征，則君臣同利，刀幣無禁，則姦貞並行。","chunks":[["故山澤無征，則君臣同利，刀幣無禁，則姦貞並行。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-3_s-8","passageId":"yan-tie-lun_ch-4_p-3","order":8,"canonicalText":"夫臣富則相侈，下專利則相傾也。","chunks":[["夫臣富則相侈，下專利則相傾也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-3_s-9","passageId":"yan-tie-lun_ch-4_p-3","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-4_s-1","passageId":"yan-tie-lun_ch-4_p-4","order":1,"canonicalText":"文學曰：「古者，市朝而無刁幣，各以其所有易所無，抱布貿絲而已。","chunks":[["文學曰：「古者，市朝而無刁幣，各以其所有易所無，抱布貿絲而已。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-4_s-2","passageId":"yan-tie-lun_ch-4_p-4","order":2,"canonicalText":"後世即有龜貝金錢，交施之也。","chunks":[["後世即有龜貝金錢，交施之也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-4_s-3","passageId":"yan-tie-lun_ch-4_p-4","order":3,"canonicalText":"幣數變而民滋偽。","chunks":[["幣數變而民滋偽。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-4_s-4","passageId":"yan-tie-lun_ch-4_p-4","order":4,"canonicalText":"夫救偽以質，防失以禮。","chunks":[["夫救偽以質，防失以禮。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-4_s-5","passageId":"yan-tie-lun_ch-4_p-4","order":5,"canonicalText":"湯、文繼衰，革法易化，而殷、周道興。","chunks":[["湯、文繼衰，革法易化，而殷、周道興。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-4_s-6","passageId":"yan-tie-lun_ch-4_p-4","order":6,"canonicalText":"漢初乘弊，而不改易，畜利變幣，欲以反本，是猶以煎止燔，以火止沸也。","chunks":[["漢初乘弊，而不改易，畜利變幣，欲以反本，是猶以煎止燔，以火止沸也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-4_s-7","passageId":"yan-tie-lun_ch-4_p-4","order":7,"canonicalText":"上好禮則民闇飾，上好貨則下死利也。","chunks":[["上好禮則民闇飾，上好貨則下死利也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-4_s-8","passageId":"yan-tie-lun_ch-4_p-4","order":8,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-5_s-1","passageId":"yan-tie-lun_ch-4_p-5","order":1,"canonicalText":"大夫曰：「文帝之時，縱民得鑄錢、冶鐵、煮鹽。","chunks":[["大夫曰：「文帝之時，縱民得鑄錢、冶鐵、煮鹽。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-5_s-2","passageId":"yan-tie-lun_ch-4_p-5","order":2,"canonicalText":"吳王擅鄣海澤，鄧通專西山。","chunks":[["吳王擅鄣海澤，鄧通專西山。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-5_s-3","passageId":"yan-tie-lun_ch-4_p-5","order":3,"canonicalText":"山東奸猾，咸聚吳國，秦、雍、漢、蜀因鄧氏。","chunks":[["山東奸猾，咸聚吳國，秦、雍、漢、蜀因鄧氏。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-5_s-4","passageId":"yan-tie-lun_ch-4_p-5","order":4,"canonicalText":"吳、鄧錢布天下，故有鑄錢之禁。","chunks":[["吳、鄧錢布天下，故有鑄錢之禁。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-5_s-5","passageId":"yan-tie-lun_ch-4_p-5","order":5,"canonicalText":"禁禦之法立，而奸偽息，奸偽息，則民不期於妄得，而各務其職；","chunks":[["禁禦之法立，而奸偽息，奸偽息，則民不期於妄得，而各務其職；","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-5_s-6","passageId":"yan-tie-lun_ch-4_p-5","order":6,"canonicalText":"不反本何為？","chunks":[["不反本何為？","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-5_s-7","passageId":"yan-tie-lun_ch-4_p-5","order":7,"canonicalText":"故統一，則民不二也；","chunks":[["故統一，則民不二也；","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-5_s-8","passageId":"yan-tie-lun_ch-4_p-5","order":8,"canonicalText":"幣由上，則下不疑也。","chunks":[["幣由上，則下不疑也。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-5_s-9","passageId":"yan-tie-lun_ch-4_p-5","order":9,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-6_s-1","passageId":"yan-tie-lun_ch-4_p-6","order":1,"canonicalText":"文學曰：「往古，幣眾財通而民樂。","chunks":[["文學曰：「往古，幣眾財通而民樂。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-6_s-2","passageId":"yan-tie-lun_ch-4_p-6","order":2,"canonicalText":"其後，稍去舊幣，更行白金龜龍，民多巧新幣。","chunks":[["其後，稍去舊幣，更行白金龜龍，民多巧新幣。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-6_s-3","passageId":"yan-tie-lun_ch-4_p-6","order":3,"canonicalText":"幣數易而民益疑。","chunks":[["幣數易而民益疑。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-6_s-4","passageId":"yan-tie-lun_ch-4_p-6","order":4,"canonicalText":"於是廢天下諸錢，而專命水衡三官作。","chunks":[["於是廢天下諸錢，而專命水衡三官作。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-6_s-5","passageId":"yan-tie-lun_ch-4_p-6","order":5,"canonicalText":"吏匠侵利，或不中式，故有薄厚輕重。","chunks":[["吏匠侵利，或不中式，故有薄厚輕重。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-6_s-6","passageId":"yan-tie-lun_ch-4_p-6","order":6,"canonicalText":"農人不習，物類比之，信故疑新，不知姦貞。","chunks":[["農人不習，物類比之，信故疑新，不知姦貞。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-6_s-7","passageId":"yan-tie-lun_ch-4_p-6","order":7,"canonicalText":"商賈以美貿惡，以半易倍。","chunks":[["商賈以美貿惡，以半易倍。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-6_s-8","passageId":"yan-tie-lun_ch-4_p-6","order":8,"canonicalText":"買則失實，賣則失理，其疑或滋益甚。","chunks":[["買則失實，賣則失理，其疑或滋益甚。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-6_s-9","passageId":"yan-tie-lun_ch-4_p-6","order":9,"canonicalText":"夫鑄偽金錢以有法，而錢之善惡無增損於故。","chunks":[["夫鑄偽金錢以有法，而錢之善惡無增損於故。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-6_s-10","passageId":"yan-tie-lun_ch-4_p-6","order":10,"canonicalText":"擇錢則物稽滯，而用人尤被其苦。","chunks":[["擇錢則物稽滯，而用人尤被其苦。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-6_s-11","passageId":"yan-tie-lun_ch-4_p-6","order":11,"canonicalText":"春秋曰：『算不及蠻、夷則不行。","chunks":[["春秋曰：『算不及蠻、夷則不行。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-6_s-12","passageId":"yan-tie-lun_ch-4_p-6","order":12,"canonicalText":"』故王者外不鄣海澤以便民用，內不禁刀幣以通民施。","chunks":[["』故王者外不鄣海澤以便民用，內不禁刀幣以通民施。","zh-Hant"]]},{"id":"yan-tie-lun_ch-4_p-6_s-13","passageId":"yan-tie-lun_ch-4_p-6","order":13,"canonicalText":"」","chunks":[["」","zh-Hant"]]}]}') as WorkBundle
